func TestMultipleGroupSamePathMiddleware(t *testing.T) {
	e := New()
	var calls []string
	m1 := func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			calls = append(calls, "g1")
			return next(c)
		}
	}
	m2 := func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			calls = append(calls, "g2")
			return next(c)
		}
	}
	g1 := e.Group("/api", m1)
	g2 := e.Group("/api", m2)
	g1.GET("/one", func(c Context) error { return c.String(http.StatusOK, "one") })
	g2.GET("/two", func(c Context) error { return c.String(http.StatusOK, "two") })

	req := httptest.NewRequest(http.MethodGet, "/api/one", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	t.Logf("g1 req: code=%d body=%q calls=%v", rec.Code, rec.Body.String(), calls)
	if rec.Code != 200 || rec.Body.String() != "one" {
		t.Fatalf("group1 route failed")
	}
	if len(calls) != 1 || calls[0] != "g1" {
		t.Fatalf("group1 middleware leak: %v", calls)
	}

	calls = nil
	req = httptest.NewRequest(http.MethodGet, "/api/two", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	t.Logf("g2 req: code=%d body=%q calls=%v", rec.Code, rec.Body.String(), calls)
