// bindDataToMap binds data to a map destination. Only limited map types are supported:
// - map[string][]string,
// - map[string]string <-- (binds first value from data slice)
// - map[string]interface{}
// You are better off binding to struct as Go does not support binding to maps with
// arbitrary types.
// Optional arguments are accepted so that callers which have already resolved the
// destination type and value can pass them along; they are not needed as both are
// derived from destination.
func (b *DefaultBinder) bindDataToMap(destination interface{}, data map[string][]string, _ ...interface{}) error {
	val := reflect.ValueOf(destination)
	if val.Kind() == reflect.Ptr {
		val = val.Elem()
	}
	if !val.IsValid() || val.Kind() != reflect.Map || val.Type().Key().Kind() != reflect.String {
		return nil
	}
	typ := val.Type()

	elemKind := typ.Elem().Kind()
	isElemInterface := elemKind == reflect.Interface
	isElemString := elemKind == reflect.String
	isElemSliceOfStrings := elemKind == reflect.Slice && typ.Elem().Elem().Kind() == reflect.String

	if !(isElemSliceOfStrings || isElemString || isElemInterface) {
		return nil
	}
	if val.IsNil() {
		if !val.CanSet() {
			return nil
		}
		val.Set(reflect.MakeMap(typ))
	}
	for k, v := range data {
		if isElemString {
			if len(v) == 0 {
				continue
			}
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
		} else {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
		}
	}
	return nil
}

